	}
}

func mustPGUUID(t *testing.T, raw string) pgtype.UUID {
	t.Helper()
	uid, err := pgutil2.PgUUID(raw)
	if err != nil {
		t.Fatalf("parse uuid %s: %v", raw, err)
	}
	return uid
}

