	}

	expectedOrgUID, _ := pgutil2.PgUUID(validOrgID)
	if store.upsertOrgID != expectedOrgUID {
		t.Fatalf("upserted org_id = %v, want %s", store.upsertOrgID, validOrgID)
	}

